public class Product {
    private String name;
    private double price;
    private String category;

    // Use 1: Field disambiguation — this.name is the field, name is the parameter
    public Product(String name, double price, String category) {
        this.name = name;         // without this.  Java would assign parameter to itself
        this.price = price;
        this.category = category;
    }

    // Use 2: Constructor chaining — this() delegates to the full constructor above
    // this() MUST be the very first statement — nothing can come before it
    public Product(String name, double price) {
        this(name, price, "General");  // calls the three-arg constructor
    }

    public Product(String name) {
        this(name, 0.0);              // chains to two-arg, which chains to three-arg
    }

    // Use 3: Returning this for method chaining (fluent interface)
    public Product applyDiscount(double percent) {
        this.price = this.price * (1 - percent / 100.0);
        return this;  // caller can chain: product.applyDiscount(10).applyDiscount(5)
    }

    // this CANNOT be used in a static method — compile error
    public static void printInfo(Product p) {
        System.out.println(p.name);  // OK: using a parameter
        // System.out.println(this.name);  // COMPILE ERROR: no object context
    }

    public static void main(String[] args) {
        Product laptop = new Product("Laptop");
        // Constructor chain: Product("Laptop") -> Product("Laptop", 0.0)
        //                 -> Product("Laptop", 0.0, "General")
        System.out.println(laptop.name + " / " + laptop.category);
        // Output: Laptop / General
    }
}
