class Account {
    protected double balance;

    // Parent constructor — requires a balance argument
    Account(double balance) {
        this.balance = balance;
    }

    String describe() {
        return "Balance: " + balance;
    }
}

class SavingsAccount extends Account {
    private double rate;

    SavingsAccount(double balance, double rate) {
        super(balance);   // super() MUST be first — passes balance to Account constructor
        // If you write ANY statement before super(), it is a compile error
        this.rate = rate; // only runs after parent is initialized
    }

    @Override
    String describe() {
        // super.describe() calls Account's version — extend, don't replace
        return super.describe() + ", rate: " + rate;
    }
}

public class SuperDemo {
    public static void main(String[] args) {
        SavingsAccount sa = new SavingsAccount(1000.0, 0.04);
        System.out.println(sa.describe());
        // Output: Balance: 1000.0, rate: 0.04
        // Without super.describe() we'd print only ", rate: 0.04"
    }
}
