public class Customer {
    private String name;
    private String email;
    private String phone;

    // The most complete constructor — this one calls super() (inserted by Java)
    public Customer(String name, String email, String phone) {
        // Java invisibly inserts: super();
        this.name = name;
        this.email = email;
        this.phone = phone;
    }

    // Simpler constructor — delegates to three-arg via this()
    // this() must be the FIRST statement — cannot write anything before it
    public Customer(String name, String email) {
        this(name, email, null);  // chains to the three-arg constructor above
    }

    // Simplest constructor — delegates to two-arg, which chains further
    public Customer(String name) {
        this(name, "noemail@example.com");  // chains to two-arg above
    }

    // ILLEGAL — cannot have both; uncomment to see compile error:
    // public Customer(String name) {
    //     super();                // compile error: super() must be first
    //     this(name, "", null);  // compile error: this() must be first
    //                            // and you cannot have two 'firsts'
    // }
}

class PremiumCustomer extends Customer {
    private int rewardPoints;

    public PremiumCustomer(String name, String email, int rewardPoints) {
        super(name, email);       // calls Customer(name, email) — must be first
        this.rewardPoints = rewardPoints;
    }
}
